@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <http://example.org/activity1> ;
            sh:resultMessage "Node ex:agent1 does not conform to one or more shapes in [ sh:class prov:Agent ] , <https://www.ogc.org/rules/prov/strict/#NotDescribedInGraph>" ;
            sh:resultPath prov:wasAssociatedWith ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape <https://www.ogc.org/rules/prov/strict/#prop-wasAssociatedWith> ;
            sh:value <http://example.org/agent1> ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
